async function parseJsonResponse<T>(
  res: Response,
  request?: { method?: string; url?: string },
): Promise<T> {
  const contentType = res.headers.get("content-type")?.toLowerCase() ?? "";

  if (!contentType.includes("application/json")) {
    const body = await res.text();
    const preview = body.slice(0, 200).trim() || res.statusText || "Empty response body";
    const error = new Error(
      `Expected JSON response but received ${contentType || "unknown content type"}: ${preview}`,
    );

    await reportHandledError({
      error,
      request,
      response: { status_code: res.status },
    });

    throw error;
  }

  return (await res.json()) as T;
}

export async function apiRequest(
  method: string,
  url: string,
  data?: unknown | undefined,
): Promise<Response> {
  const headers: Record<string, string> = data ? { "Content-Type": "application/json" } : {};

  // Add auth token if available
  const token = getAuthToken();
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  try {
    const res = await fetch(url, {
      method,
      headers,
      body: data ? JSON.stringify(data) : undefined,
      credentials: "include",
    });

    await throwIfResNotOk(res, { method, url });
    return res;
  } catch (error) {
    await reportHandledError({
      error,
      request: { method, url },
    });
    throw error;
  }
}

